@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Mock
    private PaymentGateway paymentGateway;
    @Mock
    private AuditLogger auditLogger;

    @InjectMocks
    private PaymentService paymentService;

    @Test
    void shouldHandleGatewayTimeout() {
        // Stub non-void method to throw exception
        when(paymentGateway.processPayment(any()))
            .thenThrow(new GatewayTimeoutException("Connection timed out"));

        var exception = assertThrows(PaymentFailedException.class, 
            () -> paymentService.processOrder(new Order(1L, "Item", 50.0)));

        assertThat(exception.getMessage()).contains("Gateway unavailable");
    }

    @Test
    void shouldHandleAuditLogFailure() {
        // Stub void method to throw exception using doThrow
        doThrow(new IOException("Disk full"))
            .when(auditLogger).logTransaction(anyString());

        assertDoesNotThrow(() -> paymentService.recordPayment("TXN123"));
    }
}
