@ExtendWith(MockitoExtension.class)
class DefaultReturnBehaviorTest {
    @Mock
    private ProductRepository productRepository;

    @Test
    void demonstratesDefaultReturnValues() {
        // Non-stubbed method returning object: returns null
        Product product = productRepository.findById(999L).orElse(null);
        assertThat(product).isNull();

        // Non-stubbed method returning primitive: returns zero
        int count = productRepository.countByCategory("Electronics");
        assertThat(count).isEqualTo(0);

        // Non-stubbed method returning boolean: returns false
        boolean exists = productRepository.existsById(999L);
        assertThat(exists).isFalse();

        // Non-stubbed method returning collection: returns empty list
        var products = productRepository.findAll();
        assertThat(products).isEmpty();
    }
}
