@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    @Mock
    private OrderRepository orderRepository;
    @InjectMocks
    private OrderService orderService;

    @Test
    void testCreateOrder() {
        // Simulate repository saving with generated ID
        when(orderRepository.save(any(Order.class)))
            .thenAnswer(inv -> {
                Order input = inv.getArgument(0, Order.class);
                return new Order(999L, input.item(), input.quantity()); // Add ID
            });

        var created = orderService.createOrder("Laptop", 2);

        assertThat(created.id()).isEqualTo(999L);
        assertThat(created.item()).isEqualTo("Laptop");
    }

    @Test
    void testTransformInput() {
        when(orderRepository.findByItemName(anyString()))
            .thenAnswer(inv -> {
                String itemName = inv.getArgument(0, String.class);
                return Optional.of(new Order(1L, itemName.toUpperCase(), 1));
            });

        var found = orderService.findByItemName("laptop");
        assertThat(found.item()).isEqualTo("LAPTOP"); // Transformed
    }
}
