@ExtendWith(MockitoExtension.class)
class PaymentServiceTest {
    @Mock
    private PaymentGateway paymentGateway;
    @InjectMocks
    private PaymentService paymentService;

    @Test
    void testRetryOnFailure() {
        // First call fails, second succeeds
        when(paymentGateway.processPayment(anyString()))
            .thenReturn("FAILED")
            .thenReturn("SUCCESS");

        String result = paymentService.processWithRetry("txn-123");

        assertThat(result).isEqualTo("SUCCESS");
        verify(paymentGateway, times(2)).processPayment("txn-123");
    }

    @Test
    void testPaginatedFetch() {
        // Simulate three pages of results
        when(paymentGateway.fetchTransactions(anyInt()))
            .thenReturn(
                List.of("txn-1", "txn-2"),
                List.of("txn-3", "txn-4"),
                List.of() // Empty list signals end
            );

        var allTransactions = paymentService.fetchAllTransactions();

        assertThat(allTransactions).hasSize(4);
        verify(paymentGateway, times(3)).fetchTransactions(anyInt());
    }
}
