@ExtendWith(MockitoExtension.class)
class OrderServiceTest {
    private List<String> orderList;

    @Test
    void whenThenCausesRealMethodCall() {
        orderList = new ArrayList<>(List.of("order-1"));
        var spy = spy(orderList);

        // This CALLS list.get(0) during stubbing!
        // If index is out of bounds, test setup fails
        when(spy.get(0)).thenReturn("stubbed-order");

        assertThat(spy.get(0)).isEqualTo("stubbed-order");
    }

    @Test
    void doReturnAvoidsRealMethodCall() {
        orderList = new ArrayList<>(); // Empty list
        var spy = spy(orderList);

        // This does NOT call list.get(0) during stubbing
        // Safe even though index 0 doesn't exist
        doReturn("stubbed-order").when(spy).get(0);

        assertThat(spy.get(0)).isEqualTo("stubbed-order");
    }

    @Test
    void demonstratingSideEffect() {
        var service = spy(new OrderService());

        // Real method increments counter during stubbing!
        when(service.processOrder("ord-1")).thenReturn("OK");
        // counter is now 1 from setup, not from actual test execution

        doReturn("OK").when(service).processOrder("ord-2");
        // counter remains 0, real method not called during stubbing
    }
}
